package dev.forgesworn.sapflow.broadcaster

import java.io.ByteArrayOutputStream
import java.io.IOException
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.StandardOpenOption.APPEND
import java.util.ArrayDeque
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder

/** Deterministic real local-file IO with generated bytes. No Android runtime,
 * document provider, native mux or media-playability claim. */
class RecordingLibraryOwnerTest {
    @get:Rule val temporary = TemporaryFolder()
    private class Queue {
        val work = ArrayDeque<Runnable>()
        val replies = ArrayDeque<() -> Unit>()
        fun run() = work.removeFirst().run()
        fun reply() = replies.removeFirst().invoke()
    }
    private fun owner(root: Path, queue: Queue) = RecordingLibraryOwner(root, { queue.work.add(it) }, { queue.replies.add(it) })
    private fun finished(root: Path): RecordingCatalogue.Entry {
        val store = RecordingCatalogue(root)
        val writer = store.begin(store.newShow(CaptureProfile.DEFAULT).nextIdentity())
        val file = RecordingFile(root, writer.filename)
        file.write(ByteArray(129_001) { (it % 127).toByte() }, false)
        file.finish(); writer.finalised(1500)
        return store.scan().single()
    }

    @Test fun cancelledQueuedPreflightDoesNoIoAndRetainsCapacityUntilWorkerAcknowledges() {
        val root = temporary.root.toPath().resolve("not-created")
        val queue = Queue(); val owner = owner(root, queue)
        var delivered = false
        val ticket = checkNotNull(owner.prepare(CaptureProfile.DEFAULT) { delivered = true })
        owner.cancel(ticket)
        assertFalse(owner.idle); assertNull(owner.scan {})
        assertFalse(Files.exists(root))
        queue.run()
        assertTrue(owner.idle); assertFalse(Files.exists(root)); assertFalse(delivered)
        assertTrue(queue.replies.isEmpty())
    }

    @Test fun delayedScanCannotReplaceANewerScan() {
        val root = temporary.root.toPath().resolve("recordings")
        finished(root)
        val queue = Queue(); val owner = owner(root, queue)
        var old = false; var fresh = false
        checkNotNull(owner.scan { old = true }); queue.run()
        checkNotNull(owner.scan { fresh = it.getOrThrow().size == 1 })
        queue.reply(); assertFalse(old)
        queue.run(); queue.reply(); assertTrue(fresh)
    }

    @Test fun pickerAndQueuedExportOwnNoFileHandlesAndCopyOnlyTheExactSelection() {
        val root = temporary.root.toPath().resolve("recordings"); val entry = finished(root)
        val original = root.resolve(entry.identity!!.filename)
        val queue = Queue(); val owner = owner(root, queue)
        val selected = checkNotNull(owner.select(entry, false))
        assertNull(owner.select(entry, false)); assertFalse(owner.idle)
        var opens = 0; var result: Result<Long>? = null
        val output = ByteArrayOutputStream()
        assertTrue(owner.export(selected, { opens++; output }) { result = it })
        assertEquals(0, opens); assertFalse(owner.export(selected, { error("stale picker") }) {})
        queue.run(); assertEquals(1, opens); assertTrue(owner.idle)
        assertNull(result); queue.reply(); assertEquals(entry.bytes, result!!.getOrThrow())
        assertArrayEquals(Files.readAllBytes(original), output.toByteArray())
    }

    @Test fun cancelledQueuedExportNeverOpensTheDocumentProvider() {
        val root = temporary.root.toPath().resolve("recordings"); val entry = finished(root)
        val queue = Queue(); val owner = owner(root, queue)
        val selected = checkNotNull(owner.select(entry, false))
        assertTrue(owner.export(selected, { error("cancelled provider must not open") }) { error("cancelled reply") })
        owner.cancelCopy(); assertFalse(owner.idle)
        queue.run(); assertTrue(owner.idle); assertTrue(queue.replies.isEmpty())
        assertEquals(entry.bytes, Files.size(root.resolve(entry.identity!!.filename)))
    }

    @Test fun cancellationDuringCopyClosesActualOwnersBeforeReleasingCapacity() {
        val root = temporary.root.toPath().resolve("recordings"); val entry = finished(root)
        val queue = Queue(); val owner = owner(root, queue)
        var closed = false
        val output = object : ByteArrayOutputStream() {
            override fun write(bytes: ByteArray, offset: Int, length: Int) {
                assertTrue(length <= 64 * 1024); assertFalse(owner.idle)
                super.write(bytes, offset, length); owner.cancelCopy()
            }
            override fun close() { assertFalse(owner.idle); closed = true; super.close() }
        }
        assertTrue(owner.export(checkNotNull(owner.select(entry, false)), { output }) { error("cancelled reply") })
        queue.run()
        assertTrue(closed); assertTrue(owner.idle); assertTrue(queue.replies.isEmpty())
        assertTrue(output.size() < entry.bytes)
        RecordingCatalogue(root).openExport(entry).use { it.copyTo(ByteArrayOutputStream()) }
    }

    @Test fun outputCloseFailureRetainsCapacityAfterTheSourceHasActuallyClosed() {
        val root = temporary.root.toPath().resolve("recordings"); val entry = finished(root)
        val queue = Queue(); val owner = owner(root, queue)
        val output = object : ByteArrayOutputStream() { override fun close() { throw IOException("generated close failure") } }
        var result: Result<Long>? = null
        assertTrue(owner.export(checkNotNull(owner.select(entry, false)), { output }) { result = it })
        queue.run(); queue.reply()
        assertTrue(result!!.isFailure); assertTrue(owner.cleanupRetained); assertFalse(owner.idle)
        assertNull(owner.scan {}); assertNull(owner.prepare(CaptureProfile.DEFAULT) {})
        assertNull(owner.select(entry, false))
        assertFalse(RecordingCatalogue(root).cleanupRetained)
        assertEquals(entry.bytes, Files.size(root.resolve(entry.identity!!.filename)))
    }

    @Test fun providerFailureClosesTheSourceAndAllowsAnExplicitRetry() {
        val root = temporary.root.toPath().resolve("recordings"); val entry = finished(root)
        val queue = Queue(); val owner = owner(root, queue)
        var result: Result<Long>? = null
        assertTrue(owner.export(checkNotNull(owner.select(entry, false)), { throw IOException("generated provider failure") }) { result = it })
        queue.run(); queue.reply()
        assertTrue(result!!.isFailure); assertTrue(owner.idle)
        assertFalse(RecordingCatalogue(root).cleanupRetained)
        assertNotNull(owner.select(entry, false))
    }

    @Test fun aChangedPrivateSourceIsRefusedBeforeOpeningTheChosenDocument() {
        val root = temporary.root.toPath().resolve("recordings"); val entry = finished(root)
        val queue = Queue(); val owner = owner(root, queue)
        val selected = checkNotNull(owner.select(entry, false))
        Files.write(root.resolve(entry.identity!!.filename), byteArrayOf(1), APPEND)
        var result: Result<Long>? = null
        assertTrue(owner.export(selected, { error("changed selection must not open provider") }) { result = it })
        queue.run(); queue.reply()
        assertTrue(result!!.isFailure); assertTrue(owner.idle)
        assertFalse(RecordingCatalogue(root).cleanupRetained)
        assertEquals(entry.bytes + 1, Files.size(root.resolve(entry.identity.filename)))
    }

    @Test fun scanningAHealthyLiveWriterDoesNotBecomeUncertainCleanup() {
        val root = temporary.root.toPath().resolve("recordings")
        val store = RecordingCatalogue(root)
        val writer = store.begin(store.newShow(CaptureProfile.DEFAULT).nextIdentity())
        val file = RecordingFile(root, writer.filename)
        file.write(byteArrayOf(1, 2, 3), false)
        val queue = Queue(); val owner = owner(root, queue)
        try {
            var entries: List<RecordingCatalogue.Entry>? = null
            checkNotNull(owner.scan { entries = it.getOrThrow() }); queue.run(); queue.reply()
            assertEquals(RecordingCatalogue.State.WRITING, entries!!.single().state)
            assertTrue(owner.idle); assertFalse(owner.cleanupRetained)
            var preparation: Result<RecordingLibraryOwner.Preparation>? = null
            checkNotNull(owner.prepare(CaptureProfile.DEFAULT) { preparation = it }); queue.run(); queue.reply()
            assertTrue(preparation!!.isFailure); assertTrue(owner.idle); assertFalse(owner.cleanupRetained)
        } finally { file.abort(); writer.cancel(); writer.ownersClosed() }
    }

    @Test fun fullCatalogueRefusesRecordingDuringPreflightAndPreservesFiles() {
        val root = temporary.root.toPath().resolve("recordings")
        val store = RecordingCatalogue(root)
        val show = store.newShow(CaptureProfile.DEFAULT)
        repeat(256) { Files.write(root.resolve(show.nextIdentity().filename), byteArrayOf(1)) }
        val queue = Queue(); val owner = owner(root, queue)
        var result: Result<RecordingLibraryOwner.Preparation>? = null
        checkNotNull(owner.prepare(CaptureProfile.DEFAULT) { result = it }); queue.run(); queue.reply()
        assertTrue(result!!.isFailure)
        assertEquals(RecordingCatalogue.Failure.CAPACITY, (result!!.exceptionOrNull() as RecordingCatalogue.CatalogueFailure).reason)
        assertTrue(owner.idle); assertFalse(owner.cleanupRetained)
        assertEquals(256, store.scan().size)
    }
}
